mapper.select:
/* selectMonsterDetailList - Optimized with JOIN */ SELECT max(m1.kr_name) as m1_kr_name , m1.image_url AS image_url1 , max(m2.kr_name) as m2_kr_name , m2.image_url AS image_url2 , max(m3.kr_name) as m3_kr_name , m3.image_url AS image_url3 , count(1) AS total_count , ROUND(100.0 * SUM(CASE WHEN bll.win_lose = '1' THEN 1 ELSE 0 END) / COUNT(*), 1) AS total_rate , SUM(CASE WHEN bll.win_lose = '1' THEN 1 end) AS win_count , SUM(CASE WHEN bll.win_lose = '2' THEN 1 end) AS lose_count , max(m1.leader_id) as leader_id , max(ml1.type) as leader_type , max(ml1.stat) as leader_stat , max(ml1.increase_by) as leader_increase_by , max(ml1.icon_path) as leader_icon , get_leader_skill_desc(max(ml1.type), max(ml1.stat), max(ml1.increase_by)) as leader_skill_description FROM ( SELECT vbdi.match_id, vbdi.log_timestamp, vbdi.type, coalesce(mcm1.original_monster_id, vbdi.monster_id_1) AS monster_id_1, least(coalesce(mcm2.original_monster_id, vbdi.monster_id_2), coalesce(mcm3.original_monster_id, vbdi.monster_id_3)) AS monster_id_2, greatest(coalesce(mcm2.original_monster_id, vbdi.monster_id_2), coalesce(mcm3.original_monster_id, vbdi.monster_id_3)) AS monster_id_3 FROM view_battle_deck_info vbdi left join monster_collaboration_mapping mcm1 on vbdi.monster_id_1 = mcm1.collaboration_monster_id left join monster_collaboration_mapping mcm2 on vbdi.monster_id_2 = mcm2.collaboration_monster_id left join monster_collaboration_mapping mcm3 on vbdi.monster_id_3 = mcm3.collaboration_monster_id WHERE vbdi.type = 'defense' AND vbdi.monster_id_1 IN (${dm1_list}) AND LEAST(vbdi.monster_id_2, vbdi.monster_id_3) IN (${dm2_list}) AND GREATEST(vbdi.monster_id_2, vbdi.monster_id_3) IN (${dm3_list})
AND vbdi.match_id = #{match_id}
) vbdi LEFT JOIN battle_log_list bll ON vbdi.match_id = bll.match_id AND vbdi.log_timestamp = bll.log_timestamp LEFT JOIN monster m1 ON vbdi.monster_id_1 = m1.monster_id LEFT JOIN monster m2 ON vbdi.monster_id_2 = m2.monster_id LEFT JOIN monster m3 ON vbdi.monster_id_3 = m3.monster_id LEFT JOIN monster_leaders ml1 ON m1.leader_id = ml1.leader_id WHERE 1=1
AND EXISTS ( SELECT 1 FROM guild_siege_battle_log gsbl WHERE gsbl.match_id = bll.match_id AND gsbl.guild_id = #{view_guild_id}::text )
AND EXISTS ( SELECT 1 FROM guild_siege_battle_log gsbl WHERE gsbl.match_id = bll.match_id AND gsbl.guild_id = #{sess_guild_id}::text )
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR SUBSTRING(bll.match_id, 1, 6) >= (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1) )
AND bll.opp_guild_id IN
#{guild_id}
GROUP BY m1.image_url, m2.image_url, m3.image_url ORDER BY total_count DESC, total_rate DESC

/* selectMonsterDetailTeamListCount - 공덱 이력 전체 개수 조회 */ select count(1) as total_count from ( select coalesce(mcm1.original_monster_id, vbdi2.monster_id_1) as monster_id_1 , least(coalesce(mcm2.original_monster_id, vbdi2.monster_id_2), coalesce(mcm3.original_monster_id, vbdi2.monster_id_3)) AS monster_id_2 , greatest(coalesce(mcm2.original_monster_id, vbdi2.monster_id_2), coalesce(mcm3.original_monster_id, vbdi2.monster_id_3)) AS monster_id_3 from view_battle_deck_info vbdi1 join view_battle_deck_info vbdi2 on vbdi1.match_id = vbdi2.match_id and vbdi1.log_timestamp = vbdi2.log_timestamp and vbdi2.type = 'attack' left join monster_collaboration_mapping mcm1 on vbdi2.monster_id_1 = mcm1.collaboration_monster_id left join monster_collaboration_mapping mcm2 on vbdi2.monster_id_2 = mcm2.collaboration_monster_id left join monster_collaboration_mapping mcm3 on vbdi2.monster_id_3 = mcm3.collaboration_monster_id join battle_log_list bll on vbdi1.match_id = bll.match_id and vbdi1.log_timestamp = bll.log_timestamp where vbdi1.type = 'defense'
and exists ( select 1 from guild_siege_battle_log gsbl where gsbl.match_id = bll.match_id and gsbl.guild_id = #{view_guild_id}::text )
and exists ( select 1 from guild_siege_battle_log gsbl where gsbl.match_id = bll.match_id and gsbl.guild_id = #{sess_guild_id}::text )
and vbdi1.monster_id_1 IN (${dm1_list}) and LEAST(vbdi1.monster_id_2, vbdi1.monster_id_3) IN (${dm2_list}) and GREATEST(vbdi1.monster_id_2, vbdi1.monster_id_3) IN (${dm3_list})
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR SUBSTRING(bll.match_id, 1, 6) >= (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1) )
and vbdi1.match_id = #{match_id}
and bll.opp_guild_id IN
#{guild_id}
group by coalesce(mcm1.original_monster_id, vbdi2.monster_id_1) , least(coalesce(mcm2.original_monster_id, vbdi2.monster_id_2), coalesce(mcm3.original_monster_id, vbdi2.monster_id_3)) , greatest(coalesce(mcm2.original_monster_id, vbdi2.monster_id_2), coalesce(mcm3.original_monster_id, vbdi2.monster_id_3)) ) a

