mapper.insert:
/* insertArenaInfoBulk — rta_match (시즌은 played_at 으로 rta_season 매핑, 실패 시 _FALLBACK) */
INSERT INTO public.rta_match (
	replay_id,
	season_id,
	played_at,
	winner_wizard_id,
	battle_version,
	battle_type
) VALUES

(
	#{m.rid}
	, COALESCE(
		(SELECT s.season_id FROM public.rta_season s
		 WHERE s.start_at <= (#{m.date_add})::timestamptz AND s.end_at > (#{m.date_add})::timestamptz
		 ORDER BY s.sort_order ASC, s.season_no DESC
		 LIMIT 1),
		(SELECT s2.season_id FROM public.rta_season s2 WHERE s2.season_code = '_FALLBACK' LIMIT 1)
	)
	, (#{m.date_add})::timestamptz
	, #{m.wizard_id}
	, #{m.battle_ver}
	, #{m.battle_type}
)

ON CONFLICT (replay_id) DO NOTHING

INSERT INTO public.rta_match_participant (
	replay_id,
	wizard_id,
	wizard_name,
	channel_uid,
	team_side,
	country_code,
	rating_id,
	ladder_score,
	ladder_rank,
	is_winner,
	is_first_pick,
	alive_count,
	leader_pick_slot
) VALUES

(
	#{m.rid}
	, #{m.wizard_id}
	, #{m.wizard_name}
	, #{m.channel_uid}
	, COALESCE(#{m.team_no,jdbcType=SMALLINT}, 1)
	, #{m.country}
	, #{m.rating_id,jdbcType=INTEGER}
	, #{m.score,jdbcType=INTEGER}
	, #{m.rank_no,jdbcType=INTEGER}
	, COALESCE(#{m.is_winner,jdbcType=BOOLEAN}, false)
	, #{m.is_first_pick,jdbcType=BOOLEAN}
	, #{m.alive_count,jdbcType=SMALLINT}
	, #{m.leader_pick_slot,jdbcType=SMALLINT}
)

ON CONFLICT (replay_id, wizard_id) DO NOTHING

INSERT INTO public.rta_monster (unit_master_id, monster_name, element_code) SELECT DISTINCT c.canonical_id, COALESCE(mo.kr_name, '?'), COALESCE(mo.monster_elemental, 'unknown') FROM (
SELECT public.rta_canonical_unit_master_id(TRIM(#{m.unit_master_id}::text)::bigint) AS canonical_id
) c LEFT JOIN public.monster mo ON mo.monster_id = c.canonical_id::text ON CONFLICT (unit_master_id) DO NOTHING

mapper.select:
/* selectRecommendedAttackDeckListCount - 추천 공덱 전체 개수 조회 */
select count(1) as total_count
  from siege_recommended_attack_deck srad
 where srad.def_monster_1 = #{dm1}
   and srad.def_monster_2 = #{dm2}
   and srad.def_monster_3 = #{dm3}

/* selectRecordUserDetail */ select match_id , a.log_id , a.log_timestamp , max(a.win_lose) as win_lose , max(a.guild_name) as guild_name , max(a.wizard_name) as wizard_name , max(a.opp_guild_name) as opp_guild_name , max(a.opp_wizard_name) as opp_wizard_name , max(case when a.type = 'defense' then m1.image_url end) as defense_monster_1 , max(case when a.type = 'defense' then m2.image_url end) as defense_monster_2 , max(case when a.type = 'defense' then m3.image_url end) as defense_monster_3 , max(case when a.type = 'attack' then m1.image_url end) as attack_monster_1 , max(case when a.type = 'attack' then m2.image_url end) as attack_monster_2 , max(case when a.type = 'attack' then m3.image_url end) as attack_monster_3 , max(case when a.type = 'defense' then m1.leader_id end) as defense_leader_id , max(case when a.type = 'defense' then ml1.type end) as defense_leader_type , max(case when a.type = 'defense' then ml1.stat end) as defense_leader_stat , max(case when a.type = 'defense' then ml1.increase_by end) as defense_leader_increase_by , max(case when a.type = 'defense' then ml1.icon_path end) as defense_leader_icon , max(case when a.type = 'defense' then get_leader_skill_desc(ml1.type, ml1.stat, ml1.increase_by) end) as defense_leader_skill_description , max(case when a.type = 'attack' then m1.leader_id end) as attack_leader_id , max(case when a.type = 'attack' then ml1.type end) as attack_leader_type , max(case when a.type = 'attack' then ml1.stat end) as attack_leader_stat , max(case when a.type = 'attack' then ml1.increase_by end) as attack_leader_increase_by , max(case when a.type = 'attack' then ml1.icon_path end) as attack_leader_icon , max(case when a.type = 'attack' then get_leader_skill_desc(ml1.type, ml1.stat, ml1.increase_by) end) as attack_leader_skill_description from (select vbdi.match_id , vbdi.log_id , vbdi.log_timestamp , vbdi.type , bll.win_lose , bll.guild_name , bll.wizard_name , bll.opp_guild_name , bll.opp_wizard_name , case when mcm1.original_monster_id is null then vbdi.monster_id_1 else mcm1.original_monster_id end AS monster_id_1 , case when mcm2.original_monster_id is null then vbdi.monster_id_2 else mcm2.original_monster_id end AS monster_id_2 , case when mcm3.original_monster_id is null then vbdi.monster_id_3 else mcm3.original_monster_id end AS monster_id_3 from view_battle_deck_info vbdi LEFT JOIN monster_collaboration_mapping mcm1 ON vbdi.monster_id_1 = mcm1.collaboration_monster_id LEFT JOIN monster_collaboration_mapping mcm2 ON vbdi.monster_id_2 = mcm2.collaboration_monster_id LEFT JOIN monster_collaboration_mapping mcm3 ON vbdi.monster_id_3 = mcm3.collaboration_monster_id join (select bll.* , gsbl.guild_name , gsbl2.guild_name as opp_guild_name from battle_log_list bll left join guild_siege_battle_log gsbl on bll.match_id = gsbl.match_id and bll.guild_id = gsbl.guild_id left join guild_siege_battle_log gsbl2 on bll.match_id = gsbl2.match_id and bll.opp_guild_id = gsbl2.guild_id where 1=1
AND bll.guild_id = #{sess_guild_id}::text
) bll on vbdi.match_id = bll.match_id and vbdi.log_id = bll.log_id and bll.wizard_id = #{wizard_id} ) a LEFT JOIN monster m1 ON a.monster_id_1 = m1.monster_id LEFT JOIN monster m2 ON a.monster_id_2 = m2.monster_id LEFT JOIN monster m3 ON a.monster_id_3 = m3.monster_id LEFT JOIN monster_leaders ml1 ON m1.leader_id = ml1.leader_id WHERE 1 = 1
AND EXISTS ( SELECT 1 FROM guild_siege_season gss WHERE gss.season_no = #{season_no}::int AND TO_DATE(SUBSTRING(a.match_id, 1, 6), 'YYYYMM') >= gss.start_date AND (gss.end_date IS NULL OR TO_DATE(SUBSTRING(a.match_id, 1, 6), 'YYYYMM') <= gss.end_date) )
group by a.match_id, a.log_id, a.log_timestamp order by a.log_timestamp desc

/* selectDeckDetail - 공덱 상세 정보 조회 */ SELECT srad.id as deck_id, srad.def_monster_1, srad.def_monster_2, srad.def_monster_3, srad.atk_monster_1, srad.atk_monster_2, srad.atk_monster_3, ( (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'UP') + (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id IS NULL AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'UP' AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_1::text) LIMIT 1), TRIM(v.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_2::text) LIMIT 1), TRIM(v.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_3::text) LIMIT 1), TRIM(v.atk_monster_3::text)) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_1::text) LIMIT 1), TRIM(srad.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_2::text) LIMIT 1), TRIM(srad.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_3::text) LIMIT 1), TRIM(srad.atk_monster_3::text)) ]::text[]) AS t(u) ) ) ) AS recommend_count, ( (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'DOWN') + (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id IS NULL AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'DOWN' AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_1::text) LIMIT 1), TRIM(v.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_2::text) LIMIT 1), TRIM(v.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_3::text) LIMIT 1), TRIM(v.atk_monster_3::text)) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_1::text) LIMIT 1), TRIM(srad.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_2::text) LIMIT 1), TRIM(srad.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_3::text) LIMIT 1), TRIM(srad.atk_monster_3::text)) ]::text[]) AS t(u) ) ) ) AS not_recommend_count, COALESCE( (SELECT v.vote_type FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND #{sess_user_id} IS NOT NULL AND v.user_id = #{sess_user_id}::text LIMIT 1), (SELECT v.vote_type FROM siege_deck_user_vote v WHERE v.deck_id IS NULL AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND #{sess_user_id} IS NOT NULL AND v.user_id = #{sess_user_id}::text AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_1::text) LIMIT 1), TRIM(v.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_2::text) LIMIT 1), TRIM(v.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(v.atk_monster_3::text) LIMIT 1), TRIM(v.atk_monster_3::text)) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_1::text) LIMIT 1), TRIM(srad.atk_monster_1::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_2::text) LIMIT 1), TRIM(srad.atk_monster_2::text)), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = TRIM(srad.atk_monster_3::text) LIMIT 1), TRIM(srad.atk_monster_3::text)) ]::text[]) AS t(u) ) LIMIT 1) ) AS my_vote, -- 몬스터1 정보 m1.kr_name as m1_kr_name, m1.image_url as image_url1, COALESCE(stats1.hp, 0) as m1_hp, COALESCE(stats1.atk, 0) as m1_atk, COALESCE(stats1.def, 0) as m1_def, COALESCE(stats1.spd, 0) as m1_spd, COALESCE(stats1.crit_rate, 0) as m1_crit_rate, COALESCE(stats1.crit_dmg, 0) as m1_crit_dmg, COALESCE(stats1.resistance, 0) as m1_resistance, COALESCE(stats1.accuracy, 0) as m1_accuracy, -- 몬스터2 정보 m2.kr_name as m2_kr_name, m2.image_url as image_url2, COALESCE(stats2.hp, 0) as m2_hp, COALESCE(stats2.atk, 0) as m2_atk, COALESCE(stats2.def, 0) as m2_def, COALESCE(stats2.spd, 0) as m2_spd, COALESCE(stats2.crit_rate, 0) as m2_crit_rate, COALESCE(stats2.crit_dmg, 0) as m2_crit_dmg, COALESCE(stats2.resistance, 0) as m2_resistance, COALESCE(stats2.accuracy, 0) as m2_accuracy, -- 몬스터3 정보 m3.kr_name as m3_kr_name, m3.image_url as image_url3, COALESCE(stats3.hp, 0) as m3_hp, COALESCE(stats3.atk, 0) as m3_atk, COALESCE(stats3.def, 0) as m3_def, COALESCE(stats3.spd, 0) as m3_spd, COALESCE(stats3.crit_rate, 0) as m3_crit_rate, COALESCE(stats3.crit_dmg, 0) as m3_crit_dmg, COALESCE(stats3.resistance, 0) as m3_resistance, COALESCE(stats3.accuracy, 0) as m3_accuracy FROM siege_recommended_attack_deck srad LEFT JOIN monster m1 ON srad.atk_monster_1 = m1.monster_id LEFT JOIN monster m2 ON srad.atk_monster_2 = m2.monster_id LEFT JOIN monster m3 ON srad.atk_monster_3 = m3.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats1 ON srad.id = stats1.deck_id AND srad.atk_monster_1 = stats1.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats2 ON srad.id = stats2.deck_id AND srad.atk_monster_2 = stats2.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats3 ON srad.id = stats3.deck_id AND srad.atk_monster_3 = stats3.monster_id WHERE 1=1
AND srad.id = #{deck_id}::int
AND srad.def_monster_1 = #{def_monster_1}
AND srad.def_monster_2 = #{def_monster_2}
AND srad.def_monster_3 = #{def_monster_3}
AND srad.atk_monster_1 = #{atk_monster_1}
AND srad.atk_monster_2 = #{atk_monster_2}
AND srad.atk_monster_3 = #{atk_monster_3}
LIMIT 1

mapper.insert:
/* insertDeckVoteRegistered - 추천 공덱에 등록된 행(deck_id) 투표 */
INSERT INTO siege_deck_user_vote (def_monster_1, def_monster_2, def_monster_3, deck_id, user_id, vote_type, atk_monster_1, atk_monster_2, atk_monster_3, crt_date, upt_date)
VALUES (#{def_monster_1}, #{def_monster_2}, #{def_monster_3}, #{deck_id}::int, #{sess_user_id}, #{vote_type}, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)

/* insertDeckVoteFree - 추천 공덱 미등록 조합 투표(deck_id NULL, 공격 3마리) */
INSERT INTO siege_deck_user_vote (def_monster_1, def_monster_2, def_monster_3, deck_id, user_id, vote_type, atk_monster_1, atk_monster_2, atk_monster_3, crt_date, upt_date)
VALUES (#{def_monster_1}, #{def_monster_2}, #{def_monster_3}, NULL, #{sess_user_id}, #{vote_type}, #{atk_monster_1}, #{atk_monster_2}, #{atk_monster_3}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)

mapper.delete:
/* deleteDeckVote - 추천/비추천 취소: deck_id 있으면 등록 행, 없으면 atk로 자유 투표 행 */
DELETE FROM siege_deck_user_vote
 WHERE user_id = #{sess_user_id}
   AND def_monster_1 = #{def_monster_1}
   AND def_monster_2 = #{def_monster_2}
   AND def_monster_3 = #{def_monster_3}


   AND deck_id = #{deck_id}::int


   AND deck_id IS NULL
   AND atk_monster_1 = #{atk_monster_1}
   AND atk_monster_2 = #{atk_monster_2}
   AND atk_monster_3 = #{atk_monster_3}

/* deleteDeckDetail - 공덱 삭제 */
delete
from siege_recommended_attack_deck
where 1=1

	and id = #{deck_id}::int


	and atk_monster_1 = #{atk_monster_1}


	and atk_monster_2 = #{atk_monster_2}


	and atk_monster_3 = #{atk_monster_3}

/* deleteGuildSiegeBattleDeckByMatchId - match_id 기준으로 battle_deck 삭제 */
DELETE FROM view_battle_deck_info
WHERE match_id = #{matchId}

/* deleteGuildSiegeBattleLogByMatchId - match_id 기준으로 battle_log 삭제 */
DELETE FROM battle_log_list
WHERE match_id = #{matchId}

/* deleteGuildSiegeInfoByMatchId - match_id 기준으로 guild_info 삭제 */
DELETE FROM guild_siege_battle_log
WHERE match_id = #{matchId}
